import { test, expect } from '@playwright/test';

test.describe('Stale Data Invalidation After Form Submission', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form');
  });

  test('should invalidate stale data after successful form submission', async ({ page }) => {
    // Intercept the initial data fetch
    await page.route('**/api/data', (route) => {
      route.continue();
    });

    // Verify initial stale data is displayed
    const dataDisplay = page.getByRole('region', { name: /data display/i });
    await expect(dataDisplay).toBeVisible();
    const staleValue = page.getByText('Stale Value');
    await expect(staleValue).toBeVisible();

    // Fill out the form
    const nameInput = page.getByLabel('Name');
    await nameInput.fill('John Doe');

    const emailInput = page.getByLabel('Email');
    await emailInput.fill('john@example.com');

    // Submit the form
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Wait for API response and data refresh
    await page.waitForResponse(response =>
      response.url().includes('/api/data') && response.status() === 200
    );

    // Verify success message
    const successMessage = page.getByText('Form submitted successfully');
    await expect(successMessage).toBeVisible();

    // Verify stale data is replaced with fresh data
    const freshValue = page.getByText('Fresh Value');
    await expect(freshValue).toBeVisible();
    await expect(staleValue).not.toBeVisible();
  });

  test('should handle form submission failure and keep stale data', async ({ page }) => {
    // Intercept the form submission API
    await page.route('**/api/submit', (route) => {
      route.abort('failed');
    });

    // Fill out the form
    const nameInput = page.getByLabel('Name');
    await nameInput.fill('Jane Doe');

    const emailInput = page.getByLabel('Email');
    await emailInput.fill('jane@example.com');

    // Submit the form
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Wait for error response
    await page.waitForResponse(response =>
      response.url().includes('/api/submit') && response.status() === 500
    );

    // Verify error message is displayed
    const errorMessage = page.getByText('Submission failed');
    await expect(errorMessage).toBeVisible();

    // Verify stale data is still visible
    const dataDisplay = page.getByRole('region', { name: /data display/i });
    await expect(dataDisplay).toBeVisible();
    const staleValue = page.getByText('Stale Value');
    await expect(staleValue).toBeVisible();

    // Verify fresh data is not displayed
    const freshValue = page.getByText('Fresh Value');
    await expect(freshValue).not.toBeVisible();
  });
});
